114	    .load-error-icon { width: 40px; height: 40px; background: var(--color-danger-tint); color: var(--color-danger); }
115	    .primary-button {
116	      height: 44px; padding: 0 20px; display: flex; align-items: center; gap: 8px; border: none; border-radius: 8px;
117	      background: var(--color-ink); color: var(--color-surface); font: inherit; font-size: 15px; font-weight: 600; cursor: pointer;
