120	    .empty-account-icon { width: 48px; height: 48px; background: var(--color-disabled-fill); color: var(--color-ink-2); }
121	    .empty-account p { margin: 0; font-size: 18px; line-height: 26px; font-weight: 500; }
122	    .loading-summary { display: flex; justify-content: space-between; align-items: flex-end; gap: 32px; padding: 32px 40px; }
