124	    .loading-status app-icon { color: var(--color-ink); }
125	    .skeleton-stack { display: flex; flex-direction: column; gap: 14px; margin-top: 20px; }
126	    .skeleton { display: block; height: 12px; border-radius: 6px; background: var(--color-fill-muted); animation: shimmer 1.2s ease-in-out infinite; }
127	    .heading-skeleton { width: 260px; }
128	    .figure-skeleton { width: 380px; height: 56px; border-radius: 8px; }
129	    .badge-skeleton { width: 180px; height: 40px; border-radius: 999px; margin-bottom: 10px; }
130	    .loading-table { overflow: hidden; }
131	    .skeleton-caption { padding: 24px; }
132	    .skeleton-caption .skeleton { width: 200px; }
133	    .skeleton-row { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 24px; align-items: center; height: 56px; padding: 0 24px; border-top: 1px solid var(--color-line-soft); }
134	    .skeleton-row .skeleton:nth-child(1) { width: 70px; }
135	    .skeleton-row .skeleton:nth-child(2) { width: 24px; justify-self: end; }
136	    .skeleton-row .skeleton:nth-child(3) { width: 150px; }
137	    .skeleton-row .skeleton:nth-child(4) { width: 140px; }
138	    @keyframes shimmer { 50% { opacity: 0.55; } }
139	    @media (prefers-reduced-motion: reduce) { .skeleton { animation: none; } }
140	    .page-footer { flex-shrink: 0; padding: 20px var(--page-gutter) 24px; background: var(--color-surface); border-top: 1px solid var(--color-line); }
141	    .with-footnotes { padding-top: 36px; }
142	    .footnotes { display: grid; grid-template-columns: 240px minmax(0, 1fr); gap: 48px; }
143	    .footnotes h2 { margin: 0; font-size: 14px; line-height: 20px; font-weight: 600; }
144	    .footnotes ul { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 48px; font-size: 14px; line-height: 20px; color: var(--color-ink-2); }
145	    .footer-base { margin: 0; font-size: 13px; line-height: 18px; color: var(--color-ink-3); }
146	    .with-footnotes .footer-base { margin-top: 28px; padding-top: 16px; border-top: 1px solid var(--color-line-soft); }
147	  `,
148	})
149	export class DashboardPage {
150	  protected readonly state = inject(DashboardState);
151	
152	  protected readonly lastLoadedReport = linkedSignal<ActivityHealthReport | undefined, ActivityHealthReport | undefined>({
153	    source: this.state.report,
154	    computation: (report, previous) => report ?? previous?.value,
155	  });
156	
157	  protected readonly selectedWeekRange = computed<WeekRange | null>(() => {
158	    const report = this.state.report();
159	    const week = this.state.week();
160	    if (report !== undefined) {
161	      return report.week;
162	    }
163	    return week === null ? null : { start: week, end: sundayOfWeek(week) };
164	  });
165	
166	  protected readonly stepperWeek = computed<WeekRange | null>(() => {
167	    const boundsReport = this.lastLoadedReport();
168	    return boundsReport === undefined ? null : (this.selectedWeekRange() ?? boundsReport.week);
169	  });
170	
171	  protected readonly skeletonRows = [1, 2, 3, 4];
172	
173	  protected readonly footnoteReport = computed(() => (this.state.error() ? undefined : this.state.report()));
174	
175	  protected readonly dataAsOfLabel = computed(() => {
176	    const report = this.state.report();
177	    return report?.dataAsOf ? formatCalendarDay(report.dataAsOf, report.account.timezone) : null;
178	  });
179	
180	  protected isEmptyAccount(report: ActivityHealthReport): boolean {
181	    return report.locations.length === 0 && report.summary.baseline.weeksUsed === 0;
182	  }
183	}
